#!/usr/bin/env bash
# Bundle item (thread "Videos: Social Development committee meetings", 22 Nov 2569). The item name is taken from this file's
# name, so renumbering = renaming the file. SELF-CONTAINED: the videos are inside this file (base64 tar at the end);
# nothing is read from committees/social/media.
# Puts three AFTER-meeting videos (1080x1920, Thai voice + English subtitles burned in, legal STOP 0 WARN 0; VIDEO AUTO-APPROVAL)
# on parliamentx.com/social/2569 (the cards and summaries are already live):
#   - sub-elderly.html meeting 25 (4 Nov 2569)  · source เอกสารข่าว ครั้งที่ 25 (Rpublic 1)  -> s/v-elderly-25.html
#   - sub-women.html   meeting 27 (3 Nov 2569)  · source เอกสารข่าว ครั้งที่ 27 (Rpublic 1)  -> s/v-women-27.html
#   - sub-women.html   meeting 28 (17 Nov 2569) · source เอกสารข่าว ครั้งที่ 28 (Rpublic 1)  -> s/v-women-28.html
# These replace the held items 134/135 of 17 Nov (never published). Independent of 174 (either order works).
# Surgical, same pattern as items 125/174: copies mp4/vtt/poster, sets only the "media" of those meetings in the DATA line and the
# page json (keeps any other video, before-meeting first), adds CAPS, makes the share pages (video_share.py, CARD_BIG=1) keeping every
# other share page byte-identical, adds the video block to m/<key>-<n>.html. Idempotent; no git, no network. Needs $HUB $BUILD.
set -euo pipefail
: "${HUB:?HUB not set}"; BUILD=${BUILD:-/mnt/project-files/archive/build}
T=$(basename "$0" .sh); export T
M="$HUB/social/2569"
W=$(mktemp -d); KEEP=$(mktemp -d); trap 'rm -rf "$W" "$KEEP"' EXIT
awk 'f{print} /^__PAYLOAD_BELOW__$/{f=1}' "$0" | base64 -d | tar -xzf - -C "$W"
( cd "$W" && md5sum -c --quiet MD5SUMS ) || { echo "$T: payload damaged" >&2; exit 1; }
for f in sub-elderly.html sub-elderly.json sub-women.html sub-women.json; do test -f "$M/$f" || { echo "$T: $M/$f missing" >&2; exit 1; }; done
python3 - "$M" <<'PY'
import json, os, sys
M = sys.argv[1]; dec = json.JSONDecoder(); T = os.environ['T']
for pg, n in (('sub-elderly', 25), ('sub-women', 27), ('sub-women', 28)):
    t = open(f'{M}/{pg}.html', encoding='utf-8').read()
    c = [dec.raw_decode(l[11:])[0] for l in t.split('\n') if l.startswith('const DATA=')][0]
    if not [m for m in c if m['n'] == n and not m.get('cancelled')]:
        sys.exit(f'{T}: meeting card {pg} {n} missing; nothing changed')
PY
mkdir -p "$M/media" "$M/img"
for row in "sub-elderly-v25 101" "sub-women-v27 108" "sub-women-v28 139"; do
  set -- $row; f=$1; want=$2
  dur=$(ffprobe -v error -show_entries format=duration -of csv=p=0 "$W/$f.mp4")
  python3 -c "import sys; sys.exit(0 if abs(float('$dur')-$want)<3 else 1)" || { echo "$T: $f length $dur, expected ~$want s" >&2; exit 1; }
  wh=$(ffprobe -v error -select_streams v:0 -show_entries stream=width,height -of csv=p=0 "$W/$f.mp4"); [ "$wh" = "1080,1920" ] || { echo "$T: $f size $wh" >&2; exit 1; }
  head -1 "$W/$f.th.vtt" | grep -q '^WEBVTT' || { echo "$T: $f vtt header" >&2; exit 1; }
  for e in mp4 th.vtt; do cmp -s "$W/$f.$e" "$M/media/$f.$e" 2>/dev/null || cp -f "$W/$f.$e" "$M/media/$f.$e"; done
done
for p in poster-sub-elderly-25.jpg poster-sub-women-27.jpg poster-sub-women-28.jpg; do cmp -s "$W/$p" "$M/img/$p" 2>/dev/null || cp -f "$W/$p" "$M/img/$p"; done
python3 - "$M" "$W/payload.json" <<'PY'
import json, os, sys
M, PAY = sys.argv[1], sys.argv[2]; T = os.environ['T']
D = json.load(open(PAY, encoding='utf-8'))
ser = lambda a: json.dumps(a, ensure_ascii=False, separators=(',', ':')).replace('</', '<\\/')
changed = []
def put(p, t):
    if open(p, encoding='utf-8').read() != t:
        open(p, 'w', encoding='utf-8').write(t); changed.append(os.path.relpath(p, M))
def sized(md, old):
    md = json.loads(json.dumps(md))
    for v in [md['video']] + md['videos']:
        ov = [x for x in ((old or {}).get('videos') or []) if x.get('ck') == v['ck']]
        if ov and ov[0]['src'] != v['src'] and os.path.basename(ov[0]['src']) == os.path.basename(v['src']):
            v['src'] = ov[0]['src']          # already moved to a video repo by video_offload: keep that path (idempotent)
        lp = os.path.join(M, 'media', os.path.basename(v['src']))
        v['size'] = os.path.getsize(lp) if os.path.exists(lp) else ov[0]['size']
    return md
def merge(old, md):
    new = sized(md, old)
    others = [x for x in ((old or {}).get('videos') or []) if x.get('ck') != new['video']['ck']]
    vids = others + [new['video']]
    vids.sort(key=lambda v: 0 if v.get('kind') == 'pre' else 1)   # before-meeting first, after-meeting second
    out = dict(old or {}); out['videos'] = vids; out['video'] = vids[0]
    return out
def jline(lines, pre, dump):
    idx = [i for i, l in enumerate(lines) if l.startswith(pre)]
    assert len(idx) == 1, f'{pre} not found once'
    body = lines[idx[0]][len(pre):]; val, end = json.JSONDecoder().raw_decode(body); tail = body[end:]
    assert pre + dump(val) + tail == lines[idx[0]], f'{pre} does not round-trip; not touching it'
    return idx[0], val, tail
for page, d in D.items():
    p = os.path.join(M, page); lines = open(p, encoding='utf-8').read().split('\n')
    i, arr, tail = jline(lines, 'const DATA=', ser)
    by = {str(m['n']): m for m in arr if not m.get('cancelled')}
    for n, mt in d['meetings'].items():
        by[n]['media'] = merge(by[n].get('media'), mt['media'])
    lines[i] = 'const DATA=' + ser(arr) + tail
    i, caps, tail = jline(lines, 'const CAPS=', lambda a: json.dumps(a, ensure_ascii=False))
    for ck, vtt in d['caps'].items():
        caps[ck] = open(os.path.join(M, vtt), encoding='utf-8').read()
    lines[i] = 'const CAPS=' + json.dumps(caps, ensure_ascii=False) + tail
    put(p, '\n'.join(lines))
    jp = os.path.join(M, d['json']); raw = open(jp, encoding='utf-8').read(); ms = json.loads(raw)
    assert json.dumps(ms, ensure_ascii=False, indent=1) == raw, f"{d['json']} does not round-trip"
    by = {str(m['n']): m for m in ms if not m.get('cancelled')}
    for n, mt in d['meetings'].items():
        assert n in by, f"{d['json']}: meeting {n} missing"
        by[n]['media'] = merge(by[n].get('media'), mt['media'])
    put(jp, json.dumps(ms, ensure_ascii=False, indent=1))
    for n, mt in d['meetings'].items():
        mp = os.path.join(M, 'm', mt['mpage'] + '.html'); share = mt['share']
        if not os.path.exists(mp): continue
        t = open(mp, encoding='utf-8').read()
        if share in t: continue
        go = f'<a class="go" href="../{page}#read-{n}">'
        if t.count(go) != 1: print(f'note: m/{mt["mpage"]}.html read-more link not found once; video block not added'); continue
        v = mt['media']['video']
        blk1 = (f'<a class="vid" href="../s/{share}"><img src="../{v["poster"]}" alt="" loading="lazy" width="72" height="128">'
                f'<span><b>{v["label"]}</b><small>ความยาว {v["dur"]} นาที · กดเพื่อดู</small></span></a>\n')
        if '<div class="vids">' in t:
            k = t.index('<div class="vids">'); e = t.index('</div>', k)
            put(mp, t[:e] + blk1 + t[e:])          # after-meeting video goes after any before-meeting video
        else:
            put(mp, t.replace(go, '<h2>วิดีโอ</h2>\n<div class="vids">\n' + blk1 + '</div>\n' + go))
print(f'{T}: changed', len(changed), 'text files:', ', '.join(changed) or 'none (already applied)')
PY
NEWP="v-elderly-25.html v-women-27.html v-women-28.html"
for f in "$M"/s/v-*.html; do b=$(basename "$f"); case " $NEWP " in *" $b "*) ;; *) cp -p "$f" "$KEEP/$b";; esac; done
CARD_BIG=1 python3 "$BUILD/video_share.py" "$M" https://parliamentx.com/social/2569 2569
for b in $NEWP; do test -f "$M/s/$b" || { echo "$T: share page s/$b missing" >&2; exit 1; }; python3 "$BUILD/mobile.py" "$M/s/$b" >/dev/null; done
python3 "$BUILD/no_video_dl.py" "$M/s"
for f in "$KEEP"/*.html; do cmp -s "$f" "$M/s/$(basename "$f")" || cp -f "$f" "$M/s/$(basename "$f")"; done
python3 "$BUILD/no_video_dl.py" --check "$M"
python3 - "$M" <<'PY'
import json, os, sys
M = sys.argv[1]; dec = json.JSONDecoder(); T = os.environ['T']
def data(pg):
    t = open(f'{M}/{pg}.html', encoding='utf-8').read()
    c = [dec.raw_decode(l[11:])[0] for l in t.split('\n') if l.startswith('const DATA=')][0]
    return t, {m['n']: m for m in reversed(c) if not m.get('cancelled')}
t, c = data('sub-elderly')
v = c[25]['media']['videos']; assert [x['ck'] for x in v] == ['elderly-25'] and v[0]['kind'] == 'post', 'elderly 25 post video'
assert '"25":"s/v-elderly-25.html' in t and '"elderly-25"' in t, 'elderly 25 VSHARE/CAPS'
for n in (22, 23, 24): assert [x['kind'] for x in c[n]['media']['videos']] == ['post'], f'elderly {n} video changed'
assert 'id="vidkind-js"' in t and 'id="novdl-css"' in t, 'elderly live layer missing'
t, c = data('sub-women')
for n in (27, 28):
    v = c[n]['media']['videos']; assert [x['ck'] for x in v] == [f'women-{n}'] and v[0]['kind'] == 'post', f'women {n} post video'
    assert f'"{n}":"s/v-women-{n}.html' in t and f'"women-{n}"' in t, f'women {n} VSHARE/CAPS'
for n in (23, 24, 25, 26): assert [x['kind'] for x in c[n]['media']['videos']] == ['post'], f'women {n} video changed'
assert 'id="vidkind-js"' in t and 'id="novdl-css"' in t, 'women live layer missing'
for b in ('v-elderly-25.html', 'v-women-27.html', 'v-women-28.html', 'v-elderly-24.html', 'v-women-26.html'):
    h = open(f'{M}/s/{b}', encoding='utf-8').read()
    assert '<style data-mb>' in h and 'id="novdl-css"' in h, f's/{b}: phone/no-download layer missing'
print(f'{T} OK')
PY
exit 0
